CREATE VIEW "Z_TEST_PRODUCTION_20250925"."B1_DocJournalEntryView" ( "TransType", "CreatedBy", "TransCnt", "TransCode", "StornoToTr", "ResidenNum", "OperatCode", "LocTotal", "FcTotal", "SysTotal", "TransCurr" ) AS SELECT T0."TransType" AS "TransType", T0."CreatedBy" AS "CreatedBy", COUNT(DISTINCT T0."TransId") AS "TransCnt", MAX(T0."TransCode") AS "TransCode", MAX(T0."StornoToTr") AS "StornoToTr", MAX(T0."ResidenNum") AS "ResidenNum", MAX(T0."OperatCode") AS "OperatCode", SUM(T0."LocTotal") AS "LocTotal", SUM(T0."FcTotal") AS "FcTotal", SUM(T0."SysTotal") AS "SysTotal", MAX(T0."TransCurr") AS "TransCurr" FROM  "Z_TEST_PRODUCTION_20250925"."OJDT" T0  GROUP BY T0."TransType", T0."CreatedBy" WITH READ ONLY